<script setup lang="ts">
import { reactive } from 'vue'
const form = reactive({ name: '', requirement: '', personnel: '' })
const emit = defineEmits<{ (event: 'close'): void; (event: 'save', value: typeof form): void }>()
function save() { if (form.name.trim()) emit('save', { ...form }) }
</script>
<template><div class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/40 p-4" @click.self="emit('close')"><form class="w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl" @submit.prevent="save"><div class="flex justify-between"><h2 class="text-xl font-bold">Add Department</h2><button type="button" class="text-2xl text-slate-400" aria-label="Close" @click="emit('close')">&times;</button></div><div class="mt-5 space-y-3"><input v-model="form.name" required placeholder="Department name" class="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm" /><input v-model="form.requirement" placeholder="Requirement needed" class="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm" /><input v-model="form.personnel" placeholder="Assigned personnel" class="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm" /></div><div class="mt-6 flex justify-end gap-3"><button type="button" class="rounded-lg border px-4 py-2 text-sm" @click="emit('close')">Cancel</button><button class="rounded-lg bg-purple-600 px-4 py-2 text-sm font-semibold text-white">Add Department</button></div></form></div></template>